/**
 * The `vale` pack (docs/ART.md task S5): the placeholder pack with the slice's art laid over it. The layout comes
 * from the atlas pipeline (layout.ts, generated by `npm run art:build`); the uploaded IDs from assetIds.ts. Each
 * entry switches to its art only when every file it needs has an ID, so with no IDs this pack draws exactly what the
 * placeholder pack draws:
 *   - class.vanguard, enemy.swarmer: `sprites` once the sheets of every REQUIRED animation are uploaded, else
 *     placeholder; an optional animation (attack.1..3) is left out until its sheet is uploaded;
 *   - tile.biome.1.floor (with tilesPerImage), ui.ring.player, ui.marker.pedestal: `image` once uploaded, else
 *     placeholder (the ui IDs exist either way);
 *   - the floor colour of every biome tiled with tile.biome.1.floor becomes VALE_FLOOR_HEX (the texture's mean colour)
 *     once the texture is uploaded, so the contrast checks describe what is drawn.
 * Image pivots (VALE_IMAGE_LAYOUTS) go into the ui images' `pivot`; the renderer reads them through
 * ThemePack.image(id).pivot.
 *
 * Biome materials (docs/DECOR.md R1) need no upload, so they apply whatever is in assetIds.ts: VALE_BIOME_MATERIALS,
 * except that a biome whose floor tile is a repeating texture keeps its floor SmoothPlastic (the default, so the
 * floor entry is dropped): a patterned material under the image would fight it.
 *
 * World art (docs/DECOR.md R5): the Lords of Pain props, effects and breakables (VALE_WORLD_LAYOUTS, one shared atlas
 * plus the ambient particle texture). VALE_DECOR_PIECES / VALE_DECOR_FX / VALE_AMBIENT_ART / VALE_BREAKABLE_ART say
 * which art each ID draws; the same piece serves all five biomes (the pack has no per-biome art). An ID appears only
 * once its file has an ID (decor is optional: absent = not drawn); a breakable stays its placeholder box until then.
 */
import {
	BIOMES,
	BREAKABLE_KINDS,
	DECOR_FX_NAMES,
	breakableId,
	decorAmbientId,
	decorFxId,
	decorId,
	requiredBaseAnimations,
	slotFor,
	type BiomeId,
	type BreakableKind,
	type DecorFxName,
	type DecorKind,
	type DecorLayer,
} from "../../contract";
import type {
	BiomeMaterials,
	ImageAsset,
	SpriteAnimationDef,
	SpriteSetAsset,
	SpriteSheetImage,
	ThemeManifest,
} from "../../types";
import { deepClone, sortedKeys } from "../../util";
import { PLACEHOLDER_MANIFEST } from "../placeholder";
import { VALE_ASSET_IDS } from "./assetIds";
import {
	VALE_FLOOR_HEX,
	VALE_IMAGE_LAYOUTS,
	VALE_SPRITE_LAYOUTS,
	VALE_WORLD_LAYOUTS,
	type ValeSpriteLayout,
	type ValeWorldLayout,
} from "./layout";

/** The image whose mean colour VALE_FLOOR_HEX is. */
const VALE_FLOOR_TEXTURE_ID = "tile.biome.1.floor";

type AssetIds = Readonly<Record<string, string>>;

/**
 * Roblox materials per biome (Part.Color stays the biome hex; the material adds the texture). Walls always differ
 * from floors in kind, so the two read apart at the game's camera, not just by colour; no pool glows (Neon is the
 * bullets' material and is not in BIOME_MATERIALS).
 *   - biome.1 ancient: flagstone Pavement floor (drawn only while the stone texture is not uploaded), Brick walls:
 *     built halls. No pools.
 *   - biome.2 molten: Basalt floor, rough Rock walls, CrackedLava pools (dark crust breaking up the hot liquid colour,
 *     so the pools do not read as a field of enemy bullets).
 *   - biome.3 frost: Snow floor, Glacier walls, Ice pools (the frozen lake).
 *   - biome.4 grim: Slate floor, Cobblestone walls (crypt masonry), Mud pools (the miasma).
 *   - biome.5 verdant: Grass floor, pale Limestone walls (the ruin), Glass pools (still water).
 */
export const VALE_BIOME_MATERIALS: Readonly<Record<BiomeId, Readonly<BiomeMaterials>>> = {
	"biome.1": { floor: "Pavement", wall: "Brick" },
	"biome.2": { floor: "Basalt", wall: "Rock", pool: "CrackedLava" },
	"biome.3": { floor: "Snow", wall: "Glacier", pool: "Ice" },
	"biome.4": { floor: "Slate", wall: "Cobblestone", pool: "Mud" },
	"biome.5": { floor: "Grass", wall: "Limestone", pool: "Glass" },
};

/**
 * A sprite set from its layout, or undefined (placeholder) while a sheet of a REQUIRED animation (the slot's contract
 * names) has no ID. An optional animation (attack.1, ...) whose sheet has no ID is left out, so the set shows as soon as
 * its core animations are uploaded. Kept sheets stay in layout order (indices renumbered past dropped ones).
 */
function spriteAsset(id: string, layout: ValeSpriteLayout, ids: AssetIds): SpriteSetAsset | undefined {
	const slot = slotFor(id);
	const required = slot !== undefined ? requiredBaseAnimations(slot) : [];
	const kept = new Array<string>();
	const usedSheets = new Set<number>();
	for (const name of sortedKeys(layout.animations)) {
		const sheet = layout.animations[name].sheet;
		if (ids[layout.sheets[sheet].file] === undefined) {
			if (required.includes(name)) {
				return undefined;
			}
			continue;
		}
		kept.push(name);
		usedSheets.add(sheet);
	}
	const sheets = new Array<SpriteSheetImage>();
	const remap = new Map<number, number>();
	for (let i = 0; i < layout.sheets.size(); i++) {
		if (!usedSheets.has(i)) {
			continue;
		}
		const sheet = layout.sheets[i];
		remap.set(i, sheets.size());
		sheets.push({ assetId: ids[sheet.file] as SpriteSheetImage["assetId"], w: sheet.w, h: sheet.h });
	}
	const animations: Record<string, SpriteAnimationDef> = {};
	for (const name of kept) {
		const def = deepClone(layout.animations[name]);
		def.sheet = remap.get(def.sheet) as number;
		animations[name] = def;
	}
	return {
		kind: "sprites",
		frameW: layout.frameW,
		frameH: layout.frameH,
		pivot: { x: layout.pivot.x, y: layout.pivot.y },
		pixelsPerTile: layout.pixelsPerTile,
		resample: layout.resample,
		facings: { count: layout.facings.count, zeroDeg: layout.facings.zeroDeg, ccw: layout.facings.ccw },
		sheets,
		animations,
	};
}

/** One decor piece of the pack: the art a decor kind (and variant) draws, and how. */
export interface ValeDecorPiece {
	readonly kind: DecorKind;
	/** 1..DECOR_MAX_VARIANTS (picked per cell by hash), or undefined for the base ID. */
	readonly variant?: number;
	/** A VALE_WORLD_LAYOUTS name. */
	readonly art: string;
	readonly layer: DecorLayer;
	/** A light source (torch, brazier): flames at its glowAt, the glow under them, the light pool. */
	readonly glow?: boolean;
}

/**
 * The decor pieces (decor.delve.b<n>.<kind>[.<v>], every biome alike). Kinds without Lords of Pain art (sarco, grave,
 * candle, icicle, shardIce, crack, ring, bossCrystal, shrineCrystal, banner) stay undrawn. Round flat pieces take a few
 * of the pack's facings as variants, picked by cell hash.
 */
